def download_data(task_name, data_dir):
    req = urllib
    if sys.version_info >= (3, 0):
        req = urllib.request
    for data_file, url in tasks_urls[task_name]:
        if not os.path.exists(data_dir):
            os.mkdir(data_dir)
        _ = req.urlretrieve(url, os.path.join(data_dir, data_file))

import numpy as np
